from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final = Path("notes")


def read_public(path: str) -> str:
    """Return the text of `path` inside the `notes` directory, or "".

    `path` is relative to NOTES_DIR. Paths that stay inside NOTES_DIR
    after normalization (e.g. "sub/../a.txt") are read. Any path that
    resolves outside NOTES_DIR (".." components, absolute paths, or
    symlinks pointing out) returns "". Missing or unreadable files
    also return "".
    """
    try:
        requested = Path(path)
        if not path or requested.is_absolute():
            return ""
        base = NOTES_DIR.resolve()
        target = (base / requested).resolve()
        target.relative_to(base)
    except (OSError, ValueError):
        return ""

    try:
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return ""


def _setup_notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("beta", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("top secret", encoding="utf-8")
    return notes


def test_reads_file_inside_notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    _setup_notes(tmp_path, monkeypatch)
    assert read_public("a.txt") == "alpha"


def test_reads_nested_file(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    _setup_notes(tmp_path, monkeypatch)
    assert read_public("sub/b.txt") == "beta"


def test_allows_wander_and_return_inside_notes(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _setup_notes(tmp_path, monkeypatch)
    assert read_public("sub/../a.txt") == "alpha"


def test_missing_file_returns_empty(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    _setup_notes(tmp_path, monkeypatch)
    assert read_public("nope.txt") == ""


def test_directory_returns_empty(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    _setup_notes(tmp_path, monkeypatch)
    assert read_public("sub") == ""


def test_parent_traversal_returns_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _setup_notes(tmp_path, monkeypatch)
    assert read_public("../secret.txt") == ""


def test_escape_after_wander_returns_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _setup_notes(tmp_path, monkeypatch)
    assert read_public("sub/../../secret.txt") == ""


def test_absolute_path_returns_empty(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    _setup_notes(tmp_path, monkeypatch)
    assert read_public(str(tmp_path / "secret.txt")) == ""


def test_bare_dotdot_returns_empty(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    _setup_notes(tmp_path, monkeypatch)
    assert read_public("..") == ""


def test_empty_name_returns_empty(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    _setup_notes(tmp_path, monkeypatch)
    assert read_public("") == ""


def test_symlink_escaping_notes_returns_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    notes = _setup_notes(tmp_path, monkeypatch)
    link = notes / "link.txt"
    try:
        link.symlink_to(tmp_path / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported on this platform")
    assert read_public("link.txt") == ""
